                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare by ASCII
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        # Parse the version
        parsed = parse_version(v)
        major, minor, patch, prerelease_ids = parsed

        # Create a sortable key
        # For pre-release: use a tuple that sorts before no pre-release
        if prerelease_ids is None:
            pre_sort = (1,)  # Sorts after (0, ...)
        else:
            # Convert pre-release identifiers to sortable form
            converted_ids = []
            for id_str in prerelease_ids:
