                    # Non-numeric: (1, string_value)
                    converted_ids.append((1, id_str))
            pre_sort = (0, tuple(converted_ids))

        return (major, minor, patch, pre_sort)

    # Use stable sort with the key function
    return sorted(versions, key=sort_key)

